# এসএসসি সাধারণ গণিত অধ্যায় ২ (সেট ও ফাংশন): মৌলিক সৃজনশীল প্রশ্ন — অনুশীলনী ২.১ ও ২.২, ক (২), খ (৪), গ (৪)
import json, os, sympy as sp
from fractions import Fraction as F
x=sp.symbols('x'); P=lambda X,Y:{(p,q) for p in X for q in Y}
# ---- যাচাই ----
U=set(range(1,11)); A={2,3,5,7}; B={1,3,5,7,9}
assert U-(A|B)==(U-A)&(U-B)=={4,6,8,10} and A&B=={3,5,7} and 2**3==8 and A-B=={2} and B-A=={1,9}
A={2,3}; B={1,2,3}; C={3,4}; assert P(A,B&C)==P(A,B)&P(A,C)=={(2,3),(3,3)} and 2**3==8
assert 60+50-20==90 and 100-90==10 and (60-20,50-20)==(40,30) and 40+30==70
A={1,2}; B={2,3}; C={3,4}; assert P(A,B|C)==P(A,B)|P(A,C) and len(P(A,B|C))==6 and sp.solve([2*x-sp.Symbol('y')-3,x+sp.Symbol('y')-6])=={x:3,sp.Symbol('y'):3} and (2,3) in P({1,2},{2,3})
assert 2**3-1==7 and 2**5-2**3==24 and 2**8==256
f=lambda t: t*t-5*t+6; assert f(2)==f(3)==0 and sorted(sp.solve(x**2-5*x,x))==[0,5] and sp.expand(f(x+1)-f(x))==2*x-4 and sp.expand(f(5-x)-f(x))==0 and f(1)==f(4)==2
A=[-2,-1,0,1,2]; S=[(p,q) for p in A for q in A if p+q==1]; assert S==[(-1,2),(0,1),(1,0),(2,-1)] and {(q,p) for p,q in S}==set(S)
g=(2*x+1)/(x-1); assert g.subs(x,2)==5 and sp.solve(g-3,x)==[4] and sorted(sp.solve(g-x,x))==sorted([(3-sp.sqrt(13))/2,(3+sp.sqrt(13))/2])
h=(1+x)/(1-x); assert h.subs(x,0)==1 and h.subs(x,-1)==0 and sp.simplify(h*h.subs(x,-x))==1 and sp.simplify(h.subs(x,1/x)+h)==0 and sp.solve(h-3,x)==[sp.Rational(1,2)] and sp.simplify(h.subs(x,h)+1/x)==0
R=[(p,2*p) for p in [1,2,3,4]]; assert R==[(1,2),(2,4),(3,6),(4,8)] and 4*8/2==16
